-- 2) Recrear las policies originales, tal cual estaban.
create policy admin_all_alertas_precio on public.alertas_precio as permissive for all to authenticated using (is_admin()) with check (is_admin());
create policy admin_all_aperturas on public.aperturas_caja as permissive for all to public using (((((auth.jwt() ->> 'app_metadata'::text))::jsonb ->> 'role'::text) = 'admin'::text));
create policy concesionario_select_aperturas on public.aperturas_caja as permissive for select to authenticated using (((((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'role'::text) = 'concesionario'::text) AND (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = ( SELECT auth.uid() AS uid))))));
create policy encargado_select_aperturas on public.aperturas_caja as permissive for select to authenticated using (((((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'role'::text) = 'encargado'::text) AND (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = ( SELECT auth.uid() AS uid))))));
create policy vendedor_select_aperturas on public.aperturas_caja as permissive for select to authenticated using (((((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'role'::text) = 'vendedor'::text) AND (sucursal_id = my_sucursal_id())));
create policy admin_all_auditoria_stock_items on public.auditoria_stock_items as permissive for all to authenticated using (is_admin()) with check (is_admin());
create policy staff_select_auditoria_stock_items on public.auditoria_stock_items as permissive for select to authenticated using ((is_admin() OR (auditoria_id IN ( SELECT a.id FROM auditorias_stock a WHERE (((a.sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))) OR (a.sucursal_id = my_sucursal_id())) AND movimiento_visible_por_turno(a.sucursal_id, a.fecha, a.created_at))))));
create policy admin_all_auditorias_stock on public.auditorias_stock as permissive for all to authenticated using (is_admin()) with check (is_admin());
create policy staff_select_auditorias_stock on public.auditorias_stock as permissive for select to authenticated using ((is_admin() OR (((sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))) OR (sucursal_id = my_sucursal_id())) AND movimiento_visible_por_turno(sucursal_id, fecha, created_at))));
create policy categories_admin_delete on public.categories as permissive for delete to authenticated using (is_admin());
create policy categories_admin_insert on public.categories as permissive for insert to authenticated with check (is_admin());
create policy categories_admin_update on public.categories as permissive for update to authenticated using (is_admin()) with check (is_admin());
create policy categories_select_auth on public.categories as permissive for select to authenticated using (((is_active = true) OR is_admin()));
create policy admin_all_cierres on public.cierres_caja as permissive for all to authenticated using ((((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text)) with check ((((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text));
create policy concesionario_select_cierres on public.cierres_caja as permissive for select to authenticated using (((((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'role'::text) = 'concesionario'::text) AND (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = ( SELECT auth.uid() AS uid))))));
create policy encargado_select_cierres on public.cierres_caja as permissive for select to authenticated using (((((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'role'::text) = 'encargado'::text) AND (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = ( SELECT auth.uid() AS uid))))));
create policy vendedor_select_cierres on public.cierres_caja as permissive for select to authenticated using (((((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'role'::text) = 'vendedor'::text) AND (sucursal_id = my_sucursal_id())));
create policy admin_all_contactos_crm on public.contactos_crm as permissive for all to authenticated using ((((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text)) with check ((((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text));
create policy encargado_insert_contactos_crm on public.contactos_crm as permissive for insert to authenticated with check ((sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))));
create policy encargado_select_contactos_crm on public.contactos_crm as permissive for select to authenticated using ((sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))));
create policy encargado_update_contactos_crm on public.contactos_crm as permissive for update to authenticated using ((sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid())))) with check ((sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))));
create policy ctc_pagos_select on public.cta_corriente_pagos as permissive for select to authenticated using ((is_admin() OR (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))) OR (sucursal_id = my_sucursal_id())));
create policy ctc_pagos_write on public.cta_corriente_pagos as permissive for all to authenticated using ((is_admin() OR (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))))) with check ((is_admin() OR (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid())))));
create policy admin_all_gastos on public.gastos as permissive for all to authenticated using ((((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text)) with check ((((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text));
create policy admin_all_gastos_fijos on public.gastos_fijos as permissive for all to authenticated using ((((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text)) with check ((((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text));
create policy admin_all_mercadopago_qr_orders on public.mercadopago_qr_orders as permissive for all to authenticated using (is_admin()) with check (is_admin());
create policy staff_select_mercadopago_qr_orders on public.mercadopago_qr_orders as permissive for select to authenticated using ((is_admin() OR (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))) OR (sucursal_id = my_sucursal_id())));
create policy admin_all_mercadopago_transferencias on public.mercadopago_transferencias_recibidas as permissive for all to authenticated using (is_admin()) with check (is_admin());
create policy staff_select_mercadopago_transferencias on public.mercadopago_transferencias_recibidas as permissive for select to authenticated using ((is_admin() OR (sucursal_id IS NULL) OR (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))) OR (sucursal_id = my_sucursal_id())));
create policy admin_all_movimiento_items on public.movimiento_items as permissive for all to authenticated using (is_admin()) with check (is_admin());
create policy encargado_select_movimiento_items on public.movimiento_items as permissive for select to authenticated using ((movimiento_id IN ( SELECT m.id FROM movimientos m WHERE ((m.sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))) AND ((m.created_by = auth.uid()) OR movimiento_visible_por_turno(m.sucursal_id, m.fecha, m.created_at))))));
create policy vendedor_select_movimiento_items on public.movimiento_items as permissive for select to authenticated using ((movimiento_id IN ( SELECT m.id FROM movimientos m WHERE ((m.sucursal_id = my_sucursal_id()) AND ((m.created_by = auth.uid()) OR movimiento_visible_por_turno(m.sucursal_id, m.fecha, m.created_at))))));
create policy admin_all_movimientos on public.movimientos as permissive for all to authenticated using (is_admin()) with check (is_admin());
create policy encargado_select_movimientos on public.movimientos as permissive for select to authenticated using (((sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))) AND ((created_by = auth.uid()) OR movimiento_visible_por_turno(sucursal_id, fecha, created_at))));
create policy vendedor_select_movimientos on public.movimientos as permissive for select to authenticated using (((sucursal_id = my_sucursal_id()) AND ((created_by = auth.uid()) OR movimiento_visible_por_turno(sucursal_id, fecha, created_at))));
create policy movimientos_socio_select on public.movimientos_socio as permissive for select to authenticated using ((is_admin() OR (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))) OR (sucursal_id = my_sucursal_id())));
create policy movimientos_socio_write on public.movimientos_socio as permissive for all to authenticated using ((is_admin() OR (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))))) with check ((is_admin() OR (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid())))));
create policy admin_all_nichos on public.nichos as permissive for all to authenticated using ((((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text)) with check ((((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text));
create policy staff_select_nichos on public.nichos as permissive for select to authenticated using ((((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text) = ANY (ARRAY['admin'::text, 'encargado'::text, 'vendedor'::text])));
create policy pagos_proveedor_select on public.pagos_proveedor as permissive for select to authenticated using ((is_admin() OR (sucursal_id IN ( SELECT sucursales.id FROM sucursales WHERE (sucursales.encargado_user_id = auth.uid()))) OR (sucursal_id = my_sucursal_id())));
